$:set -euo pipefail
gh auth setup-git
git fetch origin main -q
git reset --hard origin/main -q
node <<'NODE'
const fs=require('fs'),assert=require('assert');
const completed='Tasks/TasksCompleted/',queue='Tasks/User Prompt Task Queue/';
const p=completed+'user-prompt-task-1794192853-accepted-instruction.md';
const t=JSON.parse(fs.readFileSync(completed+'user-prompt-task-1794192853.json','utf8'));
const m=JSON.parse(fs.readFileSync(completed+'custom-instruction-task-completion.json','utf8'));
const text=fs.readFileSync(p,'utf8');
assert.strictEqual(t.status,'completed');
assert.strictEqual(t.acceptance.status,'accepted');
assert.strictEqual(t.acceptance.artifact,p);
assert(t.completion.accepted_by_user);
assert.strictEqual(t.completion.example_count,10);
assert.strictEqual((text.match(/^### E\d{2} /gm)||[]).length,10);
for(let i=1;i<=10;i++){const id='E'+String(i).padStart(2,'0'); const part=text.split('### '+id+' — ')[1]?.split(/^### E\d{2} /m)[0];assert(part,id);for(const k of ['USER:','DECISION:','WRONG:','RIGHT:','RULE:'])assert(part.includes(k),id+':'+k);}
assert.strictEqual(m.tasks.find(x=>x.id==='1794192853').status,'completed');
assert.strictEqual(m.tasks.find(x=>x.id==='1794192853').acceptance,'accepted');
assert.strictEqual(m.tasks.find(x=>x.id==='1794193447').status,'pending_revision');
assert.strictEqual(m.tasks.find(x=>x.id==='1794193968').status,'completed');
assert(!fs.existsSync(queue+'user-prompt-task-1794192853.json'));
assert(fs.existsSync(queue+'user-prompt-task-1794193447.json'));
assert(fs.existsSync('Tasks/TasksRejected/user-prompt-task-1794192853-revision.json'));
console.log('ACCEPTED_ARTIFACT_AND_TASK_STATUS_VERIFIED');
console.log('TEN_FEW_SHOTS_AND_PREAMBLE_VERIFIED');
console.log('OTHER_TASK_STATUS_PRESERVED');
NODE
for p in Tasks/TasksCompleted/user-prompt-task-1794192853-accepted-instruction.md Tasks/TasksCompleted/user-prompt-task-1794192853.json Tasks/TasksCompleted/custom-instruction-task-completion.json; do
 local_sha="$(git hash-object "$p")"
 remote_sha="$(gh api "repos/BestNameYet/Terminals/contents/$p?ref=main" --jq .sha)"
 test "$local_sha" = "$remote_sha"
 printf 'REMOTE_BLOB_MATCH %s %s\n' "$local_sha" "$p"
done
printf 'VERIFIED_COMMIT '; git rev-parse HEAD
